  level TEXT PRIMARY KEY NOT NULL CHECK(level IN ('beginner','intermediate','advanced')),
  cefr_band TEXT NOT NULL,
  cumulative_item_target INTEGER NOT NULL CHECK(cumulative_item_target > 0),
  productive_item_target INTEGER NOT NULL CHECK(productive_item_target > 0 AND productive_item_target <= cumulative_item_target),
  goal_en TEXT NOT NULL, goal_zh TEXT NOT NULL,
  methodology_version TEXT NOT NULL, updated_at INTEGER NOT NULL
);
