CREATE TABLE smartlingo_vocabulary_items (
  id TEXT PRIMARY KEY NOT NULL,
  stable_key TEXT NOT NULL, version TEXT NOT NULL,
  target_language TEXT NOT NULL CHECK(target_language IN ('zh','en','es','ja','ko','fr','de','ru','it','pt','ar','hi')),
  level TEXT NOT NULL CHECK(level IN ('beginner','intermediate','advanced')),
  cefr_band TEXT NOT NULL, difficulty INTEGER NOT NULL CHECK(difficulty BETWEEN 1 AND 5),
  scene_key TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence > 0),
  form TEXT NOT NULL, pronunciation TEXT NOT NULL DEFAULT '',
  meaning_en TEXT NOT NULL, meaning_zh TEXT NOT NULL,
  item_kind TEXT NOT NULL CHECK(item_kind IN ('word','phrase','formula','sense')),
  productive INTEGER NOT NULL DEFAULT 1 CHECK(productive IN (0,1)),
  source_type TEXT NOT NULL DEFAULT 'smartlingo_original' CHECK(source_type='smartlingo_original'),
  review_status TEXT NOT NULL CHECK(review_status IN ('draft','ai_checked','human_reviewed','published','retired')),
  created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE UNIQUE INDEX smartlingo_vocabulary_identity_uq ON smartlingo_vocabulary_items(target_language,stable_key,version);
CREATE INDEX smartlingo_vocabulary_catalog_idx ON smartlingo_vocabulary_items(target_language,level,review_status,scene_key,sequence);
