CREATE TABLE smartlingo_smartcard_decks (
  id TEXT PRIMARY KEY NOT NULL, owner_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  class_id TEXT REFERENCES smartlingo_language_classes(id) ON DELETE CASCADE,
  target_language TEXT NOT NULL, level TEXT NOT NULL, title TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1 CHECK(version > 0), visibility TEXT NOT NULL DEFAULT 'public' CHECK(visibility IN ('private','unlisted','public')),
  share_token TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),
  created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE INDEX smartlingo_smartcard_deck_owner_idx ON smartlingo_smartcard_decks(owner_user_id,updated_at);
CREATE INDEX smartlingo_smartcard_deck_public_idx ON smartlingo_smartcard_decks(visibility,status,updated_at);
CREATE TABLE smartlingo_smartcard_items (
  deck_id TEXT NOT NULL REFERENCES smartlingo_smartcard_decks(id) ON DELETE CASCADE,
  vocabulary_item_id TEXT NOT NULL REFERENCES smartlingo_vocabulary_items(id) ON DELETE RESTRICT,
  position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 49),
  PRIMARY KEY(deck_id,vocabulary_item_id), UNIQUE(deck_id,position)
);
CREATE TABLE smartlingo_smartcard_challenge_attempts (
  id TEXT PRIMARY KEY NOT NULL, deck_id TEXT NOT NULL REFERENCES smartlingo_smartcard_decks(id) ON DELETE RESTRICT,
  deck_version INTEGER NOT NULL, attempt_number INTEGER NOT NULL CHECK(attempt_number > 0), challenger_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100), correct_count INTEGER NOT NULL, question_count INTEGER NOT NULL,
  passed INTEGER NOT NULL CHECK(passed IN (0,1)), reward_points INTEGER NOT NULL DEFAULT 0 CHECK(reward_points BETWEEN 0 AND 10),
  answer_fingerprint TEXT NOT NULL, local_date TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE UNIQUE INDEX smartlingo_smartcard_attempt_identity_uq ON smartlingo_smartcard_challenge_attempts(challenger_user_id,deck_id,deck_version,attempt_number);
CREATE UNIQUE INDEX smartlingo_smartcard_reward_once_uq ON smartlingo_smartcard_challenge_attempts(challenger_user_id,deck_id,deck_version) WHERE reward_points > 0;
CREATE INDEX smartlingo_smartcard_challenge_deck_idx ON smartlingo_smartcard_challenge_attempts(deck_id,score DESC,created_at);
CREATE TABLE smartlingo_smartcard_guest_attempts (
  id TEXT PRIMARY KEY NOT NULL, guest_key_hash TEXT NOT NULL,
  deck_id TEXT NOT NULL REFERENCES smartlingo_smartcard_decks(id) ON DELETE RESTRICT,
  deck_version INTEGER NOT NULL, attempt_number INTEGER NOT NULL CHECK(attempt_number > 0), score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100),
  correct_count INTEGER NOT NULL, question_count INTEGER NOT NULL,
  passed INTEGER NOT NULL CHECK(passed IN (0,1)), provisional_points INTEGER NOT NULL CHECK(provisional_points BETWEEN 0 AND 10),
  answer_fingerprint TEXT NOT NULL,
  local_date TEXT NOT NULL, claimed_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT,
  claimed_at INTEGER, created_at INTEGER NOT NULL
);
CREATE UNIQUE INDEX smartlingo_smartcard_guest_attempt_identity_uq ON smartlingo_smartcard_guest_attempts(guest_key_hash,deck_id,deck_version,attempt_number);
CREATE UNIQUE INDEX smartlingo_smartcard_guest_reward_once_uq ON smartlingo_smartcard_guest_attempts(guest_key_hash,deck_id,deck_version) WHERE provisional_points > 0;
CREATE INDEX smartlingo_smartcard_guest_claim_idx ON smartlingo_smartcard_guest_attempts(guest_key_hash,claimed_user_id,created_at);
