CREATE TABLE smartlingo_course_credit_policy (
  id TEXT PRIMARY KEY NOT NULL CHECK(id='default'), points_per_usd INTEGER NOT NULL CHECK(points_per_usd=100),
  challenge_pass_score INTEGER NOT NULL CHECK(challenge_pass_score BETWEEN 1 AND 100),
  challenge_reward_points INTEGER NOT NULL CHECK(challenge_reward_points BETWEEN 1 AND 100),
  daily_earn_cap INTEGER NOT NULL CHECK(daily_earn_cap > 0), max_redemption_basis_points INTEGER NOT NULL CHECK(max_redemption_basis_points BETWEEN 0 AND 10000),
  updated_at INTEGER NOT NULL
);
CREATE TABLE smartlingo_course_credit_ledger (
  id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  points INTEGER NOT NULL CHECK(points != 0), entry_type TEXT NOT NULL CHECK(entry_type IN ('challenge_earn','course_redeem','redemption_release','admin_adjustment','reversal')),
  source_type TEXT NOT NULL, source_id TEXT NOT NULL, local_date TEXT NOT NULL,
  related_entry_id TEXT REFERENCES smartlingo_course_credit_ledger(id) ON DELETE RESTRICT,
  note TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL
);
CREATE UNIQUE INDEX smartlingo_course_credit_source_uq ON smartlingo_course_credit_ledger(user_id,source_type,source_id);
CREATE INDEX smartlingo_course_credit_user_idx ON smartlingo_course_credit_ledger(user_id,created_at);
CREATE TABLE smartlingo_course_credit_redemptions (
  id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  class_id TEXT NOT NULL REFERENCES smartlingo_language_classes(id) ON DELETE RESTRICT,
  points INTEGER NOT NULL CHECK(points > 0), discount_cents INTEGER NOT NULL CHECK(discount_cents > 0),
  course_price_cents INTEGER NOT NULL CHECK(course_price_cents > 0), provider TEXT NOT NULL CHECK(provider IN ('card','crypto','credit_only')),
  provider_reference TEXT, status TEXT NOT NULL CHECK(status IN ('reserved','applied','released','reversed')),
  created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE INDEX smartlingo_course_credit_redemption_user_idx ON smartlingo_course_credit_redemptions(user_id,status,created_at);
CREATE TRIGGER smartlingo_course_credit_challenge_insert_trg
BEFORE INSERT ON smartlingo_course_credit_ledger
FOR EACH ROW WHEN NEW.entry_type='challenge_earn' AND (
  NEW.points != 10
  OR NOT EXISTS (
    SELECT 1 FROM smartlingo_smartcard_challenge_attempts attempt
    JOIN smartlingo_smartcard_decks deck ON deck.id=attempt.deck_id
    WHERE attempt.id=NEW.source_id AND attempt.challenger_user_id=NEW.user_id
      AND attempt.passed=1 AND attempt.reward_points=10 AND deck.owner_user_id!=NEW.user_id
  )
  OR COALESCE((SELECT SUM(points) FROM smartlingo_course_credit_ledger
      WHERE user_id=NEW.user_id AND entry_type='challenge_earn' AND local_date=NEW.local_date),0) + NEW.points > 50
)
BEGIN SELECT RAISE(ABORT,'invalid or capped SmartCard challenge reward'); END;
CREATE TRIGGER smartlingo_course_credit_balance_insert_trg
BEFORE INSERT ON smartlingo_course_credit_ledger
FOR EACH ROW WHEN NEW.points < 0 AND COALESCE((SELECT SUM(points) FROM smartlingo_course_credit_ledger WHERE user_id=NEW.user_id),0) + NEW.points < 0
BEGIN SELECT RAISE(ABORT,'insufficient SmartLingo course credit'); END;
