INSERT INTO smartlingo_curriculum_levels VALUES
('beginner','A1-aligned',1000,700,'Handle essential personal, home, travel, food, shopping, health and safety tasks with short rehearsed exchanges.','用简短、可反复练习的表达完成个人、居家、旅行、餐饮、购物、健康与安全等基本生活任务。','2026-08-17.1',unixepoch()),
('intermediate','A2-B1-aligned',2500,1800,'Act independently in everyday, social, study and workplace situations; narrate experiences and solve routine problems.','在日常、社交、学习和工作场景中独立沟通，叙述经历并解决常见问题。','2026-08-17.1',unixepoch()),
('advanced','B1+-B2-aligned',4000,3000,'Communicate clearly and flexibly in professional, academic and social contexts, including nuance, argument and extended discourse.','在专业、学术和社交场景中清晰灵活地交流，掌握细微含义、论证与较长表达。','2026-08-17.1',unixepoch());
INSERT INTO smartlingo_course_credit_policy VALUES('default',100,80,10,50,10000,unixepoch());
